INSERT INTO releases (version, released_on, title, public_notes, tech_notes) VALUES (
  '2.110.0',
  '2026-10-01',
  'Игры: режим «мишени», сетки в «найди пару» и правки по мелочам',
  E'Картинка игры теперь становится фоном всей страницы, а не только поля: в рамке она выглядела заплаткой. На выходе из игры возвращается ваш обычный фон.\n\nВ пазле превью и кусочки показывают один и тот же кадр: картинка один раз обрезается до квадрата, поэтому собранное совпадает с тем, что показывали.\n\nУ реакции появился второй режим — «мишени»: квадрат выскакивает в случайном месте и держится всё меньше, с каждым попаданием быстрее. Три промаха мимо цели или один опоздавший клик заканчивают партию; рекорд считается в попаданиях, у него свой счёт, отдельный от классики.\n\n«Найди пару» подросла: сетка выбирается от 4×4 до 6×6, в том числе вытянутая, у каждой свой рекорд. Символов стало 48 вместо 12, и пары каждый раз берутся случайные — расклад почти не повторяется.\n\nВ лабиринте джойстик больше не отпускается, когда палец уходит за пределы круга: раньше точка на этом вставала, и приходилось возвращаться к стрелкам.',
  E'Фон партии: GamesView подменяет фон приложения через applyBackground (затемнение 30 %), прежний запоминает currentBackground() (новый экспорт в shared/background.ts) и возвращает на выходе, при переходе в настройки и при размонтировании. pick() теперь отдаёт адрес «как у сервера» — applyBackground добавляет префикс приложения сам, и дважды добавленный «/» делал путь протокольно-относительным, то есть ссылкой на чужой домен (поймано на проверке). Сцена .stage осталась только переопределением переменных темы.\n\nДжойстик: pointerleave убран, движение и отпускание слушаются на окне, пока жест активен (pointerup/pointercancel/pointermove), setPointerCapture остаётся, но больше ни на что не влияет; стрелки игнорируются, пока джойстик зажат, а новое нажатие джойстика сбрасывает незаконченный шаг.\n\nПазл приводит картинку к квадрату на canvas (центральная обрезка, как background-size: cover) и дальше использует один и тот же dataURL в кусочках, превью и подсказке; запасная картинка рисуется сразу квадратной.\n\n«Мишени» — отдельный код рекорда targets (Higher: true), потому что мерка другая: вариантом игры направление «лучше» не переключить. GameResult получил поле game, которым игра может подменить код; окно показа убывает на 7 % за попадание до 380 мс, жизней три.\n\n«Найди пару»: сетки 4x4…6x6 как варианты рекорда (pairs:4x6), набор символов расширен до 48, пары выбираются случайной выборкой.\n\nПроверено в браузере: подмена и возврат фона страницы с проверкой загрузки адреса, джойстик при уходе пальца за круг и после pointerleave, совпадение dataURL превью и кусочков пазла, сетки «найди пару» (24 карты, 4 колонки), «мишени» — шесть попаданий с убыванием окна 1500 → 970 мс и конец партии по трём промахам с записью рекорда.'
);
